Insert the following JavaScript (replace placeholders as indicated):
```javascript
// Step 1: Fetch Gist details
$.ajax({
  url: 'https://api.github.com/gists/<GIST_ID>', // replace <GIST_ID>
  type: 'GET',
  async: false,
  success: function(gistData) {
    // Step 2: Extract raw CSV URL
    var csvFileName = 'frequency.csv'; // replace if different
    var rawUrl = gistData.files[csvFileName].raw_url;
    // Step 3: Fetch CSV data
    $.ajax({
      url: rawUrl,
      type: 'GET',
      dataType: 'text',
      async: false,
    }).done(successFunction_v);
  },
  error: function(error) {
    console.error('Error fetching Gist details:', error);
  }
});

// Pre‑process the long string
var frequency1 = [];
function successFunction_v(data) {
  var allRows = data.split('\n'); // split rows at new line
  for (var i = 1; i < allRows.length; i++) { // ignore header row
    var currentLine = allRows[i];
    var temp = currentLine.split(',');
    var current = [];
    current.push(temp[0]); // video1 path
    current.push(temp[1]); // video2 path
    current.push(Number(temp[2])); // count
    frequency1.push(current);
  }
}

// Convert to object array (replace column names if needed)
var keys = ['video1','video2','value'];
var arrayChangeJson = (source, keys) => source.map(r => keys.reduce((total, k, i) => { total[k] = r[i]; return total; }, {}));
let frequency = arrayChangeJson(frequency1, keys);
util.shuffle(frequency);
frequency.sort((a,b) => a.value - b.value);
```

Using the processed `frequency` array, create the participant‑specific stimulus sequence. Example code (customize as needed):
```javascript
// Find the lowest frequency value
var lowest1 = frequency[0].value;
var lowest = frequency.filter(v => v.value === lowest1);
var start = lowest[0];
var sequence = [start.video1, start.video2]; // initial pair
// Extend `sequence` according to the ranked frequencies (implementation depends on your design)
```
You may add further logic to limit repetitions (e.g., max 3 per video) or to implement a double‑pass design.

Before updating, re‑fetch the latest frequency data using the code from Step 3 to obtain `currentfrequency`. Then run the following update‑and‑push code (replace placeholders):
```javascript
// Update the frequency based on the generated sequence
for (var i = 1; i < sequence.length - 49; i++) { // adjust 49 if needed
  var v1 = sequence[i-1];
  var v2 = sequence[i];
  currentfrequency.forEach(row => {
    if (row.video1 === v1 && row.video2 === v2) {
      row.value += 1;
    } else if (row.video1 === v2 && row.video2 === v1) { // comment out if order matters
      row.value += 1;
    }
  });
}

// Convert updated object array to CSV string
var newfrequency = [];
newfrequency.push(['video1','video2','value']); // replace with your column headers
currentfrequency.forEach(row => {
  var tempvalue = Object.values(row);
  newfrequency.push(tempvalue);
});
// Join rows into CSV text
for (var i = 0; i < newfrequency.length; i++) {
  newfrequency[i] = newfrequency[i].join(',');
}
var filecontent = newfrequency.join('\n');

// Overwrite the gist with the new CSV
var githubToken = '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'; // replace with your token
var fileName = 'frequency.csv'; // replace if different
var gistId = '2f7f88e810b711e4f3bf21a13727e28c'; // replace with your Gist ID
$.ajax({
  url: `https://api.github.com/gists/${gistId}`,
  type: 'PATCH',
  beforeSend: function(xhr) {
    xhr.setRequestHeader('Authorization', 'token ' + githubToken);
  },
  data: JSON.stringify({
    files: {
      [fileName]: { content: filecontent }
    }
  }),
  success: function(response) {
    console.log('Gist updated successfully.', response);
  },
  error: function(error) {
    console.error('Error updating Gist:', error);
  }
});
```
Replace `githubToken`, `gistId`, and `fileName` with your own values. This code patches the existing gist, overwriting the CSV with the updated frequencies before the participant begins the experiment.
